from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")

# One or more dashes, with an optional colon at either end.
_DELIMITER_RE = re.compile(r":?-+:?")


def _escape_cell(value: object) -> str:
    """Return the cell text for ``value``, escaping pipes."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _unescape_cell(text: str) -> str:
    """Turn ``\\|`` back into ``|``, leaving other backslashes alone."""
    result: list[str] = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text) and text[i + 1] == "|":
            result.append("|")
            i += 2
        else:
            result.append(text[i])
            i += 1
    return "".join(result)


def _split_row(line: str) -> list[str]:
    """Split a line on unescaped pipes, keeping escapes in the cells."""
    cells: list[str] = []
    current: list[str] = []
    i = 0
    while i < len(line):
        char = line[i]
        if char == "\\" and i + 1 < len(line) and line[i + 1] == "|":
            current.append("\\|")
            i += 2
        elif char == "|":
            cells.append("".join(current))
            current = []
            i += 1
        else:
            current.append(char)
            i += 1
    cells.append("".join(current))
    # Missing leading/trailing pipes leave an empty edge cell behind.
    if cells and cells[0] == "":
        cells.pop(0)
    if cells and cells[-1] == "":
        cells.pop()
    return cells


def _delimiter_cell(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _pad_cell(cell: str, width: int, alignment: str | None) -> str:
    padding = width - len(cell)
    if alignment == "right":
        return " " * padding + cell
    if alignment == "center":
        left = padding // 2
        return " " * left + cell + " " * (padding - left)
    return cell + " " * padding


def _format_line(cells: list[str], widths: list[int], aligns: list) -> str:
    padded = [
        _pad_cell(cell, width, alignment)
        for cell, width, alignment in zip(cells, widths, aligns)
    ]
    return "| " + " | ".join(padded) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_escape_cell(value) for value in header]

    if align is None:
        aligns: list = [None] * len(header_cells)
    else:
        aligns = list(align)
        if len(aligns) != len(header_cells):
            raise ValueError("align must have one entry per column")
        for alignment in aligns:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    widths = [max(3, len(cell)) for cell in header_cells]

    body: list[list[str]] = []
    for row in rows:
        if len(row) > len(header_cells):
            raise ValueError("row has more cells than the header")
        cells = [_escape_cell(value) for value in row]
        cells.extend([""] * (len(header_cells) - len(cells)))
        body.append(cells)
        for index, cell in enumerate(cells):
            widths[index] = max(widths[index], len(cell))

    lines = [_format_line(header_cells, widths, aligns)]
    delimiters = [
        _delimiter_cell(width, alignment)
        for width, alignment in zip(widths, aligns)
    ]
    lines.append(_format_line(delimiters, widths, aligns))
    lines.extend(_format_line(cells, widths, aligns) for cells in body)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")

    header = [_unescape_cell(cell.strip()) for cell in _split_row(lines[0])]

    delimiter_cells = _split_row(lines[1])
    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    aligns: list[str | None] = []
    for cell in delimiter_cells:
        spec = cell.strip()
        if not _DELIMITER_RE.fullmatch(spec):
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left = spec.startswith(":")
        right = spec.endswith(":")
        if left and right:
            aligns.append("center")
        elif left:
            aligns.append("left")
        elif right:
            aligns.append("right")
        else:
            aligns.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _split_row(line)
        if len(cells) != len(header):
            raise ValueError("row has a different number of cells")
        rows.append([_unescape_cell(cell.strip()) for cell in cells])

    return header, rows, aligns
